import{_ as t,A as n,o,c as i,X as a,C as s}from"./chunks/framework.pSp8ynCZ.js";const f=JSON.parse('{"title":"Architecture","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/architecture.md","filePath":"architecture.md"}'),d={name:"rust/docs/architecture.md"};function c(l,e,p,u,h,m){const r=n("DocDiagram");return o(),i("div",null,[e[0]||(e[0]=a('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="public-layers" tabindex="-1">Public layers <a class="header-anchor" href="#public-layers" aria-label="Permalink to &quot;Public layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>store</code></td><td>Matrix streams, prepared selections, borrowed and allocating reads</td></tr><tr><td><code>scans</code></td><td>Chunk/record encoding, decoding, mapping, packing, and table construction</td></tr><tr><td><code>format</code></td><td>Byte layouts and metadata views</td></tr><tr><td><code>loader</code></td><td>Sources, schemas, accesses, workers, rings, and run lifecycle</td></tr><tr><td><code>opt</code></td><td>Offline/online cache planning, model costs, residency files, serial references</td></tr><tr><td><code>prof</code></td><td>Timing sites, masks, and reports</td></tr><tr><td><code>runtime</code></td><td>Process-wide kernel binding and CPU topology queries</td></tr></tbody></table><p>The core crate is independent of Python. Language bindings adapt these interfaces and own their language-specific arrays and lifetimes.</p><h2 id="input-preparation" tabindex="-1">Input preparation <a class="header-anchor" href="#input-preparation" aria-label="Permalink to &quot;Input preparation&quot;">​</a></h2><p>A data source reads chunk metadata and builds decode tables. Loader construction composes source, coded, standard, and output column mappings, checks conversion routes, and associates the immutable graph with execution settings.</p><p><code>prepare</code> checks file identity, sequence shape, ring compatibility, and plan binding, then opens a new run generation. Inputs and outputs are bound before worker execution begins.</p><h2 id="record-path" tabindex="-1">Record path <a class="header-anchor" href="#record-path" aria-label="Permalink to &quot;Record path&quot;">​</a></h2>',8)),s(r,{name:"record-path"}),e[1]||(e[1]=a('<p>A task owns an entire position. When schemas at that position reference the same cell, input work can be shared. Results still go to their separate output regions. The output ring publishes a slot only after all its required schema outputs are complete.</p><h2 id="frame-grid-and-generations" tabindex="-1">Frame grid and generations <a class="header-anchor" href="#frame-grid-and-generations" aria-label="Permalink to &quot;Frame grid and generations&quot;">​</a></h2><p>A run reserves a grid of page-sized frames. Planned frames hold cached pages or decoded input rows; worker-private frames hold misses. A generation word marks each cached frame&#39;s current content. Admission reads or row construction publish that generation after the content is ready. Dependent accesses wait for it.</p><p>A plan reserves frames ahead of admission by the reuse gap. The execution window cannot exceed that gap. This constrains overwrites without requiring runtime eviction decisions or a cache-directory lookup.</p><p>Decoded rows can span noncontiguous frames. Current row hits gather them into scratch before mapping and processing. The process ABI receives CSR or dense rows, not a direct borrowed paged-row representation.</p><h2 id="compiler-and-plan-ring" tabindex="-1">Compiler and plan ring <a class="header-anchor" href="#compiler-and-plan-ring" aria-label="Permalink to &quot;Compiler and plan ring&quot;">​</a></h2><p>Offline compilation builds residency intervals for a stored sequence. A fixed-plan producer expands them into per-access entries. Online compilation discovers reuse, selects rows and pages, freezes frame assignments, and publishes entries ahead of workers through a bounded PlanRing.</p><p>Entries describe misses, cached frames to wait for or admit, extra block reads, and decoded rows to build or use. <code>Planning::None</code> has no PlanRing.</p><p>The compiler advances in chunks and uses a lookahead horizon. Published entries may be split into smaller ranges; whole-chunk atomic publication is not a public guarantee. Row selection is incremental by default, with an offline global reference. See <a href="/cellpack-docs/rust/docs/planning.html">planning</a> for the actual option units and constraints.</p><h2 id="i-o-and-worker-specialization" tabindex="-1">I/O and worker specialization <a class="header-anchor" href="#i-o-and-worker-specialization" aria-label="Permalink to &quot;I/O and worker specialization&quot;">​</a></h2><p>Each worker uses io_uring or blocking preadv. io_uring queues and harvests requests; files are registered when supported. Failure to create a ring is an error, so restricted environments must select <code>Pread</code> explicitly.</p><p>Workers are specialized by profiling and cache mode. Kernel pointers are bound during context construction rather than selected per element. Per-record codec components operate on caller buffers; some loader task and I/O containers can still grow on demand. The complete runtime is not promised to be allocation-free.</p><h2 id="completion-and-failure" tabindex="-1">Completion and failure <a class="header-anchor" href="#completion-and-failure" aria-label="Permalink to &quot;Completion and failure&quot;">​</a></h2><p>Output slots carry run generations and ownership state. A lease delays reuse until all its readers finish. Cancellation wakes blocked parties; worker errors cancel the run and workers are joined before the producer returns. A new successful run requires a released previous run and compatible unleased slots. An aborted ring must be replaced.</p><p>Use counters, replay, and actual decoded values to inspect these behaviors. Historical benchmark results and design goals are not current guarantees for a different workload.</p>',15))])}const b=t(d,[["render",c]]);export{f as __pageData,b as default};
